def value_range(bits, signed):
    if signed:
        return (-(2 ** (bits - 1)), 2 ** (bits - 1) - 1)
    return (0, 2 ** bits - 1)

def fits(n, bits, signed):
    low, high = value_range(bits, signed)
    return low <= n <= high

def wrap(n, bits, signed):
    n %= 2 ** bits
    if signed and n >= 2 ** (bits - 1):
        n -= 2 ** bits
    return n

def little_endian(n, size):
    out = []
    for _ in range(size):
        out.append(n & 0xFF)
        n >>= 8
    return out
